import type { ExpansionSpec } from './types';
import { difficultyRubric } from './types';
type Ref = [string,string];
const design:Ref=['CDC Field Epidemiology Manual: Designing and Conducting Analytic Studies','https://www.cdc.gov/field-epi-manual/php/chapters/design-conduct-analyze-field-studies.html'];
const analysis:Ref=['CDC Field Epidemiology Manual: Analyzing and Interpreting Data','https://www.cdc.gov/field-epi-manual/php/chapters/analyze-interpret-data.html'];
const pk:Ref=['Merck Manual Professional: Overview of Pharmacokinetics','https://www.merckmanuals.com/professional/clinical-pharmacology/pharmacokinetics/overview-of-pharmacokinetics'];
const interaction:Ref=['FDA: Examples of Drugs that Interact with CYP Enzymes and Transporter Systems','https://www.fda.gov/drugs/drug-interactions-labeling/healthcare-professionals-fdas-examples-drugs-interact-cyp-enzymes-and-transporter-systems'];
const pharm:Ref=['Open RN Nursing Pharmacology: Pharmacokinetics and Pharmacodynamics','https://www.ncbi.nlm.nih.gov/books/NBK595000/'];
const q=(n:number,subject:string,topic:string,reasoning:ExpansionSpec['reasoning'],difficultyReason:string,stem:string,options:[string,string][],explanation:string,objective:string,reference:Ref=analysis):ExpansionSpec=>({
  code:`op26x-${String(n).padStart(4,'0')}`,concept:`research-drugs-${n}-${topic.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,reasoning,difficultyReason,
  evidenceNote:`${reference[0]} is a checked reference identity for this domain. The question is independently authored; its specific inference (${topic}) and distractors remain medically/editorially unreviewed.`,
  semanticReviewNote:`Compared against the prior 200-item topic/objective inventory. This question targets ${topic}: ${objective} It is not a change of age or wording to an earlier calculation/key.`,concerns:[],
  question:{exam:subject==='Biostatistics'?'Step 1':'Step 1',subject,system:'General Principles',topic,difficulty:difficultyRubric[reasoning],stem,options,explanation,objective,reference},
});
const S='Biostatistics',P='Pharmacology';
export const specs:ExpansionSpec[]=[
q(701,S,'Negative predictive value','application','Choose all negative tests as the denominator rather than diseased subjects.','A diagnostic study records 720 true-negative results and 80 false-negative results. The test also has 160 true positives and 40 false positives. Among patients with a negative result, what is the probability of being disease free?',[
['90%','There are 720 true negatives among 800 total negative tests.'],['80%','This is not the proportion obtained from the negative-test denominator.'],['72%','This divides true negatives by all tested people rather than negative results.'],['20%','This does not represent the proportion of negative tests without disease.']], 'Negative predictive value is TN/(TN+FN), here 720/(720+80)=0.90. The conditioning event is a negative test, so positives do not belong in the denominator. The calculation does not equal sensitivity or specificity, and predictive values vary with the disease prevalence in the tested population.','Calculate negative predictive value using only negative test outcomes.'),
q(702,S,'Positive likelihood ratio','integration','Convert sensitivity and specificity into a comparison of positive-result probabilities.','A test has sensitivity 0.90 and specificity 0.80 in a relevant population. A clinician wants the factor by which a positive result multiplies the pretest odds of disease. Which value should be used?',[
['4.5','The positive likelihood ratio is 0.90 divided by 1-0.80.'],['1.125','Dividing sensitivity by specificity uses the wrong nondiseased probability.'],['0.125','This resembles a negative likelihood ratio, not the requested positive factor.'],['0.72','Multiplying sensitivity and specificity is not a likelihood ratio.']], 'The positive likelihood ratio is sensitivity/(1-specificity)=0.90/0.20=4.5. It compares the probability of a positive result in diseased versus nondiseased people. It multiplies odds, not probability directly, so converting back from post-test odds is necessary when estimating an individual post-test probability.','Use a positive likelihood ratio as an odds multiplier.'),
q(703,S,'Negative likelihood ratio','integration','Identify a negative result in diseased and nondiseased groups before forming the ratio.','A screening test has sensitivity 0.96 and specificity 0.80. What is the likelihood ratio for a negative result, used to update the odds after the result is known?',[
['0.05','LR negative is (1-0.96)/0.80, or 0.05.'],['4.8','This is the positive likelihood ratio for these values.'],['0.20','This is the false-positive rate, not the negative likelihood ratio.'],['0.76','Subtracting the two performance measures has no likelihood-ratio meaning.']], 'A negative result occurs with probability 1-sensitivity among diseased people and specificity among nondiseased people. Their ratio is 0.04/0.80=0.05. A value well below one reduces disease odds. This does not mean that the post-test disease probability is always 5%; the starting odds still matter.','Calculate a negative likelihood ratio without confusing it with post-test probability.'),
q(704,S,'Bayesian odds update','integration','Convert probability to odds, apply the given likelihood ratio, then return to probability.','A clinician estimates a 20% pretest probability of disease. A positive result has a validated likelihood ratio of 4 for this setting. What is the resulting post-test probability, assuming the likelihood ratio applies?',[
['50%','Pretest odds are 0.2/0.8=0.25; multiplying by four gives odds of one.'],['80%','Multiplying the probability itself by four is not the correct odds update.'],['25%','This is the pretest odds expressed numerically, not the post-test probability.'],['100%','Finite odds do not imply diagnostic certainty.']], 'Pretest odds equal p/(1-p)=0.25. A likelihood ratio of 4 gives post-test odds of 1, corresponding to probability 1/(1+1)=50%. The result depends on the validity of the pretest estimate and the applicability of the test-performance data, rather than on the positive result alone.','Perform a complete probability-to-odds Bayesian diagnostic update.'),
q(705,S,'Serial testing dependence','prioritization','Recognize that shared measurement mechanisms invalidate an independence assumption.','A clinic repeats the same antibody assay on the same stored sample after a positive result. An analyst multiplies the likelihood ratio by itself, assuming two independent tests. Why may this overstate the evidence?',[
['The errors can be strongly correlated because both tests share the sample and assay mechanism','Conditional dependence means the second result may contribute little independent information.'],['Every repeated test necessarily has zero sensitivity','Repetition does not inherently eliminate the ability to detect disease.'],['Likelihood ratios can never be used for diagnostic updating','They are useful when their assumptions and context are appropriate.'],['A second test automatically eliminates all false positives','Persistent assay interference can reproduce the same erroneous result.']], 'Multiplying likelihood ratios assumes the relevant conditional independence or correctly estimated joint performance. Repeating the same assay on the same sample can reproduce cross-reactivity or handling errors. An independent confirmatory method may add more information, but its joint behavior still requires assessment rather than automatic multiplication.','Identify conditional dependence when combining diagnostic tests.'),
q(706,S,'Screening threshold tradeoff','application','Predict the direction of sensitivity and specificity changes when a cutoff is lowered.','A laboratory calls a result positive when a biomarker exceeds a cutoff. It lowers the cutoff while measuring the same underlying samples. Which paired change is expected, barring ties or unusual implementation effects?',[
['Sensitivity rises and specificity falls','More diseased and nondiseased samples will cross the lower positive threshold.'],['Sensitivity falls and specificity rises','This describes raising rather than lowering the cutoff.'],['Both must increase','A threshold change generally trades one type of classification error against the other.'],['Prevalence must double','Changing a test threshold does not alter the true disease frequency in the sample.']], 'Lowering the positive threshold labels more samples positive. This captures additional true cases but also includes more nondiseased people, tending to increase sensitivity and reduce specificity. The best operating point depends on the consequences of missed disease versus false alarms, not solely on maximizing one measure.','Predict a threshold-driven sensitivity-specificity tradeoff.'),
q(707,S,'ROC discrimination','application','Compare summary discrimination across thresholds while avoiding an accuracy claim for a specific cutoff.','Two biomarkers are evaluated for the same binary outcome. One has an area under the receiver-operating characteristic curve of 0.50. Which interpretation is most appropriate for its ability to rank a randomly chosen case above a noncase?',[
['It provides no better ranking than chance in this evaluation','An AUC near one half indicates little useful ordering discrimination.'],['It is perfectly calibrated at every predicted risk','Discrimination does not establish calibration.'],['It has 50% sensitivity at every threshold','AUC summarizes multiple thresholds and does not fix each sensitivity value.'],['It proves the disease prevalence is 50%','AUC is not the proportion of study participants with disease.']], 'ROC AUC describes ranking discrimination over possible thresholds. An AUC of 0.50 is compatible with chance ordering of case-noncase pairs. It does not describe calibration, a single sensitivity, or prevalence. The uncertainty interval and study population still matter when comparing models.' ,'Distinguish ROC ranking discrimination from calibration and prevalence.'),
q(708,S,'Calibration','integration','Separate agreement of predicted risk with observed frequency from ranking performance.','A risk model ranks patients well, but among people assigned a 30% risk only 10% experience the event. Which model property is most clearly deficient in this group?',[
['Calibration','The predicted absolute probabilities substantially exceed observed event frequency.'],['Event ascertainment is proven perfect','The comparison does not independently validate how outcomes were measured.'],['Discrimination is necessarily zero','A model can rank people well while misestimating absolute risks.'],['Sample size is necessarily one','The finding does not imply a single observation.']], 'Calibration concerns whether predicted probabilities agree with observed frequencies in comparable patients. The stated model overpredicts risk in this group despite useful ranking. Both discrimination and calibration matter when predictions guide clinical decisions; a high AUC alone does not ensure that a predicted treatment threshold is reliable.','Recognize miscalibration despite preserved risk ranking.'),
q(709,S,'Type I error','recognition','Identify the false-positive inferential event rather than a patient-level test error.','A randomized trial concludes that two treatments differ even though their true population effects are equal. Which statistical error has occurred if the null hypothesis was incorrectly rejected?',[
['Type I error','This is rejection of a true null hypothesis.'],['Type II error','This is failure to reject a false null hypothesis.'],['Loss to follow-up','That is a potential study problem rather than the specified inferential event.'],['Confounding by indication','That concerns nonrandom treatment selection, not the definition given.']], 'A type I error occurs when a true null hypothesis is rejected. The chosen alpha controls the long-run probability under the testing assumptions, not the probability that this particular published conclusion is false. Patient-level false-positive test results use related language but are a different conditional probability.','Define type I error as rejecting a true null hypothesis.'),
q(710,S,'Type II error and power','application','Translate beta into the probability of detecting a specified alternative effect.','A planned trial has a 20% probability of failing to reject the null when a prespecified clinically important difference truly exists. What is its power for that alternative under the planning assumptions?',[
['80%','Power is one minus the type II error probability beta.'],['20%','This is beta, the probability of the specified failure to detect an effect.'],['95%','This cannot be inferred from a common confidence level.'],['5%','This is a frequently chosen alpha, not the power here.']], 'Power is 1-beta, so beta=0.20 implies power=0.80 for the specified alternative. Power depends on effect size, variability, sample size, and analysis. A trial does not possess one universal power number for every possible true difference; the alternative used in planning must be stated.','Relate power to beta for a specified effect size.'),
q(711,S,'Sample size and precision','application','Use inverse square-root scaling of standard error rather than assuming linear improvement.','A study estimates a mean from independent observations with fixed population variability. Investigators quadruple the sample size while retaining the same sampling method. Approximately what happens to the standard error of the mean?',[
['It is halved','Standard error scales as standard deviation divided by the square root of sample size.'],['It is quartered','This incorrectly assumes an inverse linear relationship with sample size.'],['It doubles','More independent observations generally improve precision.'],['It becomes exactly zero','Finite samples retain sampling uncertainty.']], 'For independent observations, the standard error of a mean is sigma/sqrt(n). Multiplying n by four doubles the denominator and halves the standard error. This improves random-error precision but does not automatically remove systematic measurement error or selection bias, which may persist even in very large samples.','Apply square-root sample-size scaling to precision.'),
q(712,S,'Standard deviation versus standard error','application','Distinguish variability among people from uncertainty in their estimated mean.','Two clinics have similar patient-level blood-pressure variability. One clinic samples many more independent patients and reports a narrower interval around its mean. Which quantity directly becomes smaller through the larger sample alone?',[
['Standard error of the mean','A larger sample reduces uncertainty in the mean when underlying variability is similar.'],['The biological standard deviation must become zero','Larger samples do not eliminate variation among individual patients.'],['Every individual blood pressure must approach the mean','Sampling more people does not alter their underlying physiology.'],['The mean must fall by half','There is no such direction of change imposed by sample size.']], 'The standard deviation describes dispersion of individual values. The standard error describes precision of a sample statistic, such as the mean, and falls as independent sample size grows. Reporting a small standard error should not be used to imply that individual patients have little variation around the group mean.','Separate individual variability from uncertainty in an estimated mean.'),
q(713,S,'P-value interpretation','integration','State the probability conditional on the null without reversing the conditioning.','A prespecified analysis yields p=0.03. The statistical model and null hypothesis specify no treatment difference. Which interpretation correctly describes this p-value?',[
['Under the null and model assumptions, data at least as incompatible with the null occur with probability 0.03','The conditioning is on the null and the testing model.'],['The probability that the null is true is exactly 3%','A p-value does not directly provide that posterior probability.'],['The probability of benefit for this patient is 97%','A study-level p-value is not an individual treatment-benefit probability.'],['The treatment effect is necessarily clinically large','Statistical significance does not measure effect magnitude.']], 'A p-value quantifies the probability of the observed or more extreme test statistic under the null and stated assumptions. It is not the probability the null is true or that an individual benefits. The effect estimate, uncertainty, design quality, and clinical consequences are needed for interpretation.' ,'Interpret a p-value without reversing its conditional probability.'),
q(714,S,'Multiple testing','integration','Recognize the increased chance of any false discovery across many null tests.','Investigators examine 100 unrelated outcomes, each using alpha 0.05, and highlight whichever results reach significance. All null hypotheses are true and the tests are independent. What is the main inferential problem?',[
['The probability of at least one false-positive finding is much larger than 5%','Repeated testing increases family-wise false discovery opportunities.'],['Every highlighted result is mathematically impossible','False positives can occur even when all null hypotheses are true.'],['The per-test alpha automatically becomes 0.0005','Multiplicity correction must be planned or applied; it does not occur automatically.'],['All nonsignificant outcomes prove equivalence','Failure to reject a null does not establish equal effects.']], 'With independent tests, the chance of no false positive is 0.95^100, so the chance of at least one is 1-0.95^100, over 99%. Prespecification and appropriate multiplicity control reduce misleading selective claims. The precise correction depends on the study questions and error rate being controlled.','Recognize multiplicity when selecting significant outcomes after many tests.'),
q(715,S,'Noninferiority interpretation','prioritization','Compare a confidence bound with the prespecified harm margin rather than ordinary significance alone.','A trial defines a noninferiority margin of 3 percentage points for treatment minus control event risk. The observed difference is 0.5 points, with a 95% interval from -1 to 2 points. Higher event risk is worse. Which conclusion fits the stated margin?',[
['The interval excludes the 3-point excess-risk margin and supports noninferiority under the design assumptions','The upper bound of 2 is below the prespecified unacceptable excess.'],['The trial proves the treatments have identical effects','Noninferiority is not proof of equality.'],['Noninferiority fails because the interval includes zero','Including zero does not violate the noninferiority margin.'],['The new treatment is conclusively superior','The interval includes differences in both directions.']], 'Noninferiority asks whether an unacceptable loss of effectiveness can be excluded, using a clinically justified margin set before analysis. Here the upper bound for excess risk is below 3 points. Interpretation still depends on conduct, adherence, comparator efficacy, and analysis population; a favorable margin comparison alone cannot repair a poorly designed trial.','Interpret noninferiority using the prespecified direction and margin.'),
q(716,S,'Intention-to-treat analysis','application','Preserve randomized allocation when classifying participants despite crossover.','In a randomized trial, some participants assigned to a procedure decline it and some controls receive it elsewhere. The primary analysis keeps everyone in their original assigned group. Which approach is being used?',[
['Intention-to-treat','Analyzing by original assignment preserves the randomized comparison.'],['As-treated analysis','This reclassifies people according to treatment actually received.'],['Per-protocol analysis only','This commonly excludes or restricts major protocol deviations.'],['Case-control sampling','This selects participants by outcome rather than randomized allocation.']], 'Intention-to-treat retains the initial randomization groups despite adherence or crossover, estimating the effect of assignment to the treatment strategy. It can dilute a biological treatment effect when crossover is substantial, but avoids biases introduced by post-randomization reclassification. Missing outcome data still require careful handling.','Identify intention-to-treat analysis in a trial with treatment crossover.',design),
q(717,S,'Allocation concealment','integration','Locate the bias-prevention step before enrollment rather than after treatment begins.','A recruiter can predict the next treatment assignment from a posted alternating schedule and preferentially enrolls less ill patients before one treatment slot. Which trial safeguard most directly prevents this problem?',[
['Concealment of the allocation sequence before enrollment','Recruiters must not know the next assignment when deciding enrollment.'],['Blinding outcome analysts only','This does not prevent selective enrollment based on the next assignment.'],['Longer follow-up alone','Follow-up duration does not remove enrollment manipulation.'],['A larger sample using the same predictable schedule','More participants do not fix systematic allocation selection bias.']], 'Allocation concealment prevents foreknowledge of the next assignment from influencing enrollment. It operates before or at assignment, whereas blinding generally prevents knowledge after assignment from influencing care or measurement. Random sequence generation and concealment are separate requirements; a random list can still be compromised if recruiters can see it.','Distinguish allocation concealment from post-assignment blinding.',design),
q(718,S,'Cluster randomization','integration','Identify the unit of allocation and the resulting within-cluster correlation.','To evaluate a prescribing intervention, investigators randomize entire clinics rather than individual patients. Patients within the same clinic often have similar treatment patterns. Which analysis issue must be addressed?',[
['Correlation of outcomes within clinics','Ignoring clustering can understate uncertainty and overstate effective sample size.'],['Every patient is an independent randomized unit','The clinic, not the individual, received the random assignment.'],['The total number of patients alone fully determines power','Number and size of clusters and intracluster correlation also matter.'],['Randomization automatically eliminates all correlation','Assignment does not make patients within a clinic biologically or behaviorally independent.']], 'Cluster trials randomize groups to reduce contamination or suit a group intervention. Shared clinic practices create within-cluster correlation, reducing effective information compared with the same number of independent patients. Appropriate design and analysis account for clustering; treating all observations as independent can make confidence intervals too narrow.','Account for clustering when clinics rather than patients are randomized.',design),
q(719,S,'Crossover washout','prioritization','Assess carryover against a stable chronic condition before accepting a within-person comparison.','A crossover trial evaluates two short-acting treatments for a stable chronic symptom. Participants receive both treatments in sequence. Why is an adequate washout between periods important?',[
['It limits residual effects from the first treatment contaminating the second period','Carryover can distort the within-person treatment comparison.'],['It guarantees that disease never changes with time','Washout does not eliminate period effects or disease progression.'],['It replaces the need to randomize treatment order','Order randomization and washout address different problems.'],['It makes crossover suitable for every curative intervention','A permanent treatment effect cannot simply be washed out.']], 'Crossover designs can reduce between-person variability by allowing each participant to serve as their own control. They require conditions and interventions for which carryover and period effects can be managed. A washout reduces residual treatment activity, but irreversible cures and rapidly changing disease are generally poor fits for this design.','Evaluate carryover and washout in a crossover trial.',design),
q(720,S,'Case-control source population','prioritization','Choose controls independently of the exposure while retaining the population that produced cases.','A team investigates an uncommon infection among restaurant patrons. Cases are confirmed infected patrons. Which comparison group best supports an unbiased estimate of prior food exposure?',[
['Uninfected people sampled from the same patron source population without selecting on the suspected food','Controls should represent exposure opportunities in the population generating cases.'],['Only patrons known never to have eaten the suspected food','Selecting controls for lack of exposure can create a spurious association.'],['Healthy residents from a distant area with different menus','Their exposure opportunities may not match those of the cases.'],['Only relatives who share every meal with each case','Extreme exposure similarity can obscure informative differences.']], 'Controls should estimate the exposure distribution in the source population from which cases arose, with selection independent of the exposure under investigation. Choosing only unexposed controls predetermines a contrast and biases the association. An appropriate source group and consistent disease ascertainment are more important than selecting an arbitrary group labeled healthy.','Select case-control controls from the population generating cases.',design),
q(721,S,'Incidence density','application','Use person-time when follow-up duration differs among participants.','A cohort contributes 2,000 person-years of observation and develops 30 new disease events. Assuming each event is counted once, what is the incidence rate?',[
['15 events per 1,000 person-years','Thirty divided by 2,000 equals 0.015 events per person-year.'],['1.5% cumulative risk for each participant','A person-time rate is not automatically an individual cumulative probability.'],['30 events per person-year','This omits the total time denominator.'],['66.7 person-years per event as the incidence rate itself','This is the reciprocal time-per-event quantity, not events per time.']], 'Incidence density divides new events by the total time at risk, giving 30/2000=0.015 per person-year or 15 per 1000 person-years. It accommodates unequal observation times. Converting a rate to cumulative risk requires additional assumptions about the hazard and follow-up horizon; the two measures are not interchangeable.','Calculate an incidence rate using a person-time denominator.'),
q(722,S,'Cross-sectional temporality','integration','Identify that simultaneous exposure and outcome measurement does not establish which came first.','A survey finds that adults with insomnia use more caffeine than adults without insomnia. Both variables are measured at the same interview. Which limitation most directly impedes a causal conclusion?',[
['The temporal order between caffeine use and insomnia is uncertain','Exposure may precede symptoms, follow them, or share other causes.'],['Cross-sectional data can never describe prevalence','A cross-sectional survey is often useful for prevalence estimation.'],['A statistically significant result establishes temporal direction','Significance does not determine which event came first.'],['The design necessarily contains random assignment','The survey observes exposures rather than assigning them.']], 'A cross-sectional association measures exposure and outcome at one time, leaving temporal ordering uncertain. Insomnia may encourage caffeine use, caffeine may worsen sleep, or both may reflect other influences. The design can quantify prevalence and generate hypotheses, but this observation alone does not resolve the causal direction.','Recognize temporal ambiguity in a cross-sectional association.',design),
q(723,S,'Ecological fallacy','integration','Separate a group-level correlation from an individual-level causal inference.','Regions with higher average income have higher recorded disease incidence. An analyst concludes that every higher-income person has greater individual disease risk than a lower-income person in the same region. What is the central error?',[
['Inferring individual relationships from aggregate data','A regional association may not hold within individual-level comparisons.'],['Using a comparison group in any study','Comparisons are necessary and are not inherently erroneous.'],['Assuming a measured exposure exists','Regional income was measured; the problem is the level of inference.'],['Failure to calculate a p-value alone','Significance testing would not repair the group-to-individual inference.']], 'Ecological data summarize groups and can reflect differences in age, detection, access, or other contextual factors. A relationship between regional averages does not establish the same relationship among individuals. Individual-level data and an appropriate causal framework are required before assigning personal risk on that basis.','Identify ecological fallacy when applying regional associations to individuals.',design),
q(724,S,'Recall bias','application','Locate differential memory of past exposures after outcome status is known.','Mothers of children with a rare disorder are interviewed years after pregnancy and search their memories more intensively for medication use than control mothers. Which bias may distort the exposure comparison?',[
['Recall bias','Knowledge of the outcome can change the completeness of recalled past exposure.'],['Lead-time bias','This concerns an earlier diagnostic clock rather than exposure memory.'],['Random allocation imbalance','No randomized treatment allocation is described.'],['Immortal time bias','The issue is differential recall, not an event-free eligibility interval.']], 'Recall bias occurs when outcome status influences how past exposures are remembered or reported. Case families may seek explanations more intensively than controls. Prospectively recorded exposure data can reduce dependence on memory, though records may have their own errors. Increasing sample size does not automatically remove this systematic difference.','Recognize differential recall in retrospective exposure interviews.',design),
q(725,S,'Length-time bias','integration','Identify preferential detection of indolent disease rather than simply starting follow-up earlier.','A screening program disproportionately detects slowly growing tumors because they remain detectable without symptoms for longer. Screen-detected patients have better survival even without an effective treatment. Which bias specifically describes the preferential case mix?',[
['Length-time bias','Long preclinical duration makes indolent cases more likely to be found at a screening visit.'],['Lead-time bias alone','That refers to advancing the diagnostic clock, distinct from selecting slower disease.'],['Recall bias','This does not arise from remembering past exposures.'],['Confounding by medication adherence','No adherence comparison is described.']], 'Screening samples the detectable preclinical period. Slowly progressing disease spends longer in that period and is therefore overrepresented among screen-detected cases. This favorable case mix can improve observed survival independently of treatment and is distinct from the clock-shift effect of lead time. Mortality comparisons must account for these distortions.','Distinguish length-biased screening selection from lead-time bias.'),
q(726,S,'Immortal time bias','integration','Identify misclassified event-free time required to qualify as treated.','A database study labels patients treated if they receive a prescription at any point during the year after diagnosis. Deaths before the first prescription are assigned to the untreated group. Which bias can spuriously favor treatment?',[
['Immortal time bias','Patients must survive until treatment to enter the treated category.'],['Recall bias','Prescription timestamps do not principally depend on remembering an exposure.'],['Lead-time bias','The problem is exposure-time classification rather than earlier diagnosis.'],['Random sampling error only','Systematic assignment of pre-treatment deaths is not merely chance variation.']], 'Defining treatment using future information can assign an event-free interval to eventual recipients while placing early deaths among nonrecipients. This can create an apparent survival benefit even without efficacy. Time-varying exposure analysis or a carefully aligned design can address the timing problem; ordinary baseline classification cannot simply ignore it.','Recognize event-free exposure qualification as immortal time bias.'),
q(727,S,'Informative attrition','prioritization','Relate differential dropout to likely unobserved outcomes rather than sample size alone.','In a pain trial, many participants with worsening symptoms leave one treatment group and no further outcomes are collected. The published analysis includes only completers. What is the most important concern?',[
['Missing outcomes may be related to treatment response and bias the comparison','Excluding worsening patients can make a treatment appear more effective.'],['Randomization guarantees that all missing outcomes are harmless','Post-randomization missingness can compromise the randomized comparison.'],['A high p-value would automatically correct attrition','Significance testing cannot recover unmeasured outcome patterns.'],['Every dropout must be assigned the best possible outcome','This is unjustified and would introduce further bias.']], 'Completer-only analysis can selectively remove poor outcomes when dropout depends on symptoms or treatment. The resulting groups no longer necessarily retain the comparability established at randomization. Follow-up efforts, appropriate missing-data methods, and sensitivity analyses should examine plausible departures from assumptions rather than treating all missing values as random.','Identify response-related dropout as a threat to trial validity.'),
q(728,S,'Effect modification','integration','Interpret distinct stratum-specific effects as information rather than automatically eliminating them.','A treatment has a substantial beneficial association in younger patients and little association in older patients, with precise estimates in both strata. The difference is biologically plausible and prespecified. Which concept best describes the heterogeneous association?',[
['Effect modification','The treatment-outcome relationship differs across levels of another variable.'],['A mandatory data-entry error','Heterogeneity can be real and is not automatically a recording mistake.'],['Confounding that must always be erased by one pooled estimate','Meaningful effect heterogeneity should be reported rather than hidden.'],['Perfect equivalence in all patients','The stratum-specific estimates explicitly differ.']], 'Effect modification means the association or causal effect differs by subgroup on a specified scale. It can inform clinical interpretation and should be distinguished from confounding. A prespecified interaction assessment and its uncertainty help evaluate the pattern; comparing one significant p-value with one nonsignificant p-value is not itself a valid interaction test.','Recognize and report effect heterogeneity on a specified scale.'),
q(729,S,'Mediator adjustment','prioritization','Choose adjustment variables according to whether the target is a total causal effect.','Researchers estimate the total effect of an exercise program on blood pressure. Weight change occurs after exercise and is one proposed pathway by which exercise lowers pressure. Why might routine adjustment for weight change distort the total-effect estimate?',[
['It can block part of the causal pathway being estimated','A mediator is downstream of the exposure and may carry part of its effect.'],['Every downstream variable is a baseline confounder','A confounder is not simply any variable related to outcome.'],['Adjusting for more variables always removes all bias','Adjustment can introduce or change bias depending on the causal structure.'],['The total effect excludes all indirect pathways by definition','A total effect includes pathways through mediators.']], 'A mediator lies on a pathway from exposure to outcome. Adjusting for it can remove an indirect component and shift the question from total effect toward a direct-effect estimand, potentially with additional bias. Covariate selection should therefore follow the causal question and timing rather than an automatic rule to adjust for every available variable.','Distinguish mediators from baseline confounders when estimating total effects.'),
q(730,S,'Collider selection','synthesis','Integrate two causes of selection and infer how conditioning creates a noncausal association.','Both severe disease and excellent insurance increase the chance of admission to a specialty center. Investigators study only admitted patients and find an inverse association between insurance quality and severity. Neither causes the other in the source population. Which explanation is most plausible?',[
['Conditioning on a common effect of insurance and severity can induce an association','Admission is a collider on the pathway linking the two causes of selection.'],['The center sample proves insurance worsens disease everywhere','The selected association need not reflect a source-population causal effect.'],['Randomization assigned insurance to admitted patients','No insurance randomization occurred in this observational selection.'],['A larger admitted sample necessarily eliminates the induced association','More observations do not remove the structural selection mechanism.']], 'When two variables both influence selection, restricting analysis to selected people can create a relationship between otherwise independent causes. Here either severity or insurance can help explain admission, producing an inverse association within the center. This illustrates collider bias and why adjustment or restriction is not automatically beneficial; the causal selection structure must be considered.','Explain a selection-induced association by conditioning on a collider.'),
q(731,S,'Overmatching','prioritization','Identify matching that suppresses the exposure contrast the investigation needs.','A case-control study evaluates whether a household food exposure causes illness. Investigators choose only household members who ate exactly the same foods as cases as controls. What is the main design concern?',[
['Overmatching on exposure can remove informative exposure differences','Controls may be too similar on the very exposure being tested.'],['More similarity always guarantees stronger causal inference','Matching the exposure can obscure the association of interest.'],['Cases and controls must have different diseases by definition','Controls should reflect the source population, not follow that rule.'],['Household controls eliminate every shared environmental bias','Shared exposures can complicate rather than automatically solve the comparison.']], 'Matching should address selected confounders without destroying the exposure contrast. Choosing controls because they share the suspected exposure risks overmatching and loss of information. Household contacts can sometimes be useful, but their suitability depends on the exposure question and source population rather than convenience alone.','Recognize overmatching that removes the exposure contrast.',design),
q(732,S,'Restriction in study design','application','Identify how limiting eligibility controls one measured characteristic while narrowing generalizability.','To reduce confounding by smoking, a study enrolls only lifelong nonsmokers. Which design method is used, and what is an important limitation?',[
['Restriction, which limits inference to the eligible group','Excluding smokers prevents within-sample smoking variation but narrows applicability.'],['Randomization, which guarantees representation of smokers','No treatment assignment or inclusion of smokers is described.'],['Blinding, which conceals smoking from participants','Eligibility restriction is not concealment of exposure information.'],['A guarantee that every other confounder is absent','Other characteristics can still confound the association.']], 'Restriction controls variation in a specified characteristic by limiting eligibility. Studying only nonsmokers can reduce confounding by smoking within that group, but cannot directly estimate effects in smokers and does not control every other confounder. The eligibility rule should follow the research question and external-validity goals.','Identify restriction and its generalizability tradeoff.',design),
q(733,S,'Stratified analysis','integration','Compare crude and stratum-specific estimates to detect a distorted pooled association.','A crude exposure-disease risk ratio is 2.0. After stratification by a baseline risk factor associated with exposure, both stratum-specific ratios are near 1.0. There is no meaningful heterogeneity between strata. Which interpretation is most supported?',[
['Confounding may explain the crude association','Similar adjusted stratum estimates differ from the crude result.'],['The exposure is proven causal because the crude ratio is large','The stratified findings weaken that unadjusted interpretation.'],['Effect modification is established by identical stratum estimates','Effect modification requires differences between effects on the chosen scale.'],['Stratification creates random treatment allocation','Analysis does not retroactively randomize observational exposure.']], 'When comparable stratum-specific estimates differ from the crude estimate, the stratification variable may account for confounding under the causal assumptions. Similarity across strata argues against strong effect modification on that scale. This comparison supports an explanation but does not prove all residual confounding or measurement error has been removed.','Use crude and stratified estimates to assess confounding.'),
q(734,S,'Age standardization','integration','Recognize that a reference age distribution separates composition from age-specific risk.','Two cities have different crude mortality rates. The older city has similar age-specific rates to the younger city. What comparison best reduces distortion due solely to their different age structures?',[
['Directly standardized rates using the same reference age distribution','Applying common weights separates age composition from age-specific mortality.'],['Comparing crude totals without population denominators','Counts confound population size and age distribution.'],['Multiplying the older city rate by its population only','This does not create a comparable age-standardized rate.'],['Deleting every death over age 65 after looking at results','Post hoc deletion is not a principled common-standard comparison.']], 'Direct age standardization applies each city age-specific rates to a common set of population weights. It answers a hypothetical comparison under the same age distribution. A standardized rate is not the actual observed crude rate, and the choice of standard should be explicit rather than selected to favor a result.','Use a common age distribution to compare composition-adjusted rates.'),
q(735,S,'Healthy worker effect','integration','Identify baseline selection into employment as distinct from a protective occupational exposure.','Employees in a physically demanding industry have lower overall mortality than the general population, which includes people too ill to work. An analyst attributes all of the difference to a protective workplace chemical. Which explanation must first be considered?',[
['Healthy worker selection','People able to enter and remain in work may be healthier than the general comparison group.'],['An automatic therapeutic effect of every workplace chemical','The observed comparison does not establish this claim.'],['Lead-time advancement of cancer diagnosis alone','No diagnostic screening clock is described.'],['A mathematical impossibility of occupational mortality studies','Appropriate comparison groups can make such studies informative.']], 'Employment and continued work can select for healthier people, producing lower mortality relative to the general population even when some occupational exposures are harmful. Internal or otherwise suitable comparisons may reduce this distortion. A favorable crude mortality pattern should not be interpreted as evidence that a workplace agent is protective without addressing selection.','Recognize healthy worker selection in occupational comparisons.',design),
q(736,S,'Verification bias','prioritization','Trace how reference-standard selection depending on the index result distorts accuracy estimates.','A new diagnostic test is evaluated, but only test-positive patients undergo the definitive reference procedure. Test-negative patients are assumed disease free without follow-up. Which concern most directly threatens the reported accuracy?',[
['Partial verification bias','Disease status is established differently according to the index test result.'],['Complete independent verification of all participants','The negatives have not received an adequate reference assessment.'],['A guaranteed true sensitivity of 100%','Unverified false negatives may simply be missed.'],['Random assignment to reference testing','Testing is determined by the result, not random allocation.']], 'Accuracy estimates require a valid assessment of disease status in the relevant groups. Preferential reference testing of positives can leave false negatives undiscovered and distort performance. Appropriate verification of negatives or justified methods addressing the missing reference outcomes are needed; assuming all are healthy does not solve the problem.','Identify diagnostic verification depending on the index test result.'),
q(737,S,'Spectrum effects','integration','Relate disease severity and alternative diagnoses to test performance across settings.','A diagnostic assay performs well when evaluated in advanced cases and exceptionally healthy controls. It is then used in patients with early disease and clinically similar alternative diagnoses. Why might its apparent accuracy be lower?',[
['The clinical spectrum differs from the original evaluation','Subtle cases and realistic mimics can be harder to distinguish.'],['Sensitivity and specificity are immutable constants for every population','They can vary with case mix, thresholds and measurement conditions.'],['Every lower estimate proves laboratory fraud','Case-spectrum differences provide a plausible nonfraud explanation.'],['Predictive value is independent of case mix and prevalence','Predictive interpretation can change materially with the tested population.']], 'Selecting severe cases and healthy controls can exaggerate discrimination relative to a clinically relevant diagnostic population. Early disease may have weaker signals while mimics increase false positives. Performance should be assessed in the intended-use setting; changing predictive values alone and changing sensitivity/specificity through spectrum are related but distinct issues.','Assess diagnostic test performance in the intended clinical spectrum.'),
q(738,S,'Nondifferential exposure error','integration','State the usual attenuation tendency while avoiding an absolute law for all errors.','In a simple binary-exposure study, exposure is misclassified similarly in cases and noncases, with independent errors and other usual attenuation assumptions. What commonly happens to the estimated exposure-outcome association?',[
['It is biased toward the null','Simple nondifferential binary exposure error often dilutes the contrast.'],['It must always reverse direction in every possible study','Reversal is not the usual result under the stated assumptions.'],['It guarantees an unbiased estimate','Equal error rates do not mean that measurement error has no effect.'],['It is automatically corrected by increasing sample size','Systematic misclassification can persist in a larger study.']], 'Under standard simple binary-exposure assumptions, nondifferential misclassification often attenuates an association. This tendency is not a universal rule for complex categories, dependent errors, or every analysis. The item states the relevant assumptions so that the answer is a defensible tendency rather than the false claim that all nondifferential error must bias toward the null.','Interpret attenuation under stated nondifferential misclassification assumptions.'),
q(739,S,'Bias versus precision','application','Distinguish a repeatable measurement offset from random sampling uncertainty.','A blood-pressure device reads 8 mm Hg too high for every patient. Investigators measure 100,000 patients and obtain a very narrow interval around the mean. Which statement best describes the remaining problem?',[
['High precision does not remove the systematic measurement bias','Many observations can estimate a consistently wrong value very precisely.'],['The large sample guarantees the offset cancels','A common directional error does not average away.'],['The offset is the same as a larger standard error','Bias and random-error uncertainty describe different features.'],['A narrow interval proves the device is calibrated','Calibration requires checking measurements against a suitable standard.']], 'Increasing sample size reduces random sampling error but does not necessarily correct a systematic instrument offset. A narrow confidence interval can surround a biased estimate. Calibration and measurement validation address this problem; precision alone cannot establish that observed values are close to the true values.','Separate systematic measurement bias from statistical precision.'),
q(740,S,'Post hoc power','prioritization','Prefer effect precision and clinically relevant intervals over a restatement of nonsignificance.','A completed trial has a wide confidence interval spanning important benefit and harm. An author calculates low observed power from the same estimated effect and argues that the study proves no benefit. What is the better interpretation?',[
['The estimate is imprecise and does not establish absence of clinically important effects','The interval directly displays which effect sizes remain compatible with the data.'],['Low observed power proves equivalence','Failure to detect a difference is not an equivalence demonstration.'],['The p-value becomes zero after a power calculation','A post hoc calculation does not alter the observed test result.'],['Every uncertain trial must be discarded without describing its estimate','Uncertain results can still be reported accurately with their limits.']], 'After a study is completed, the estimated effect and its uncertainty are more informative than an observed-power number derived from the same result. A wide interval spanning important effects signals limited precision, not proof of no effect. Equivalence requires an appropriate prespecified margin and design rather than a nonsignificant finding.' ,'Interpret an imprecise trial without converting nonsignificance into equivalence.'),
q(741,S,'Paired continuous measurements','application','Identify the repeated-person structure before choosing a comparison of mean changes.','Investigators measure the same adults blood pressure before and after a short intervention. The within-person differences are approximately normally distributed. Which analysis most directly uses this paired structure to test mean change?',[
['A paired t test of individual differences','The analysis uses each person before-after difference.'],['An unpaired test treating all measurements as independent','This ignores the correlation between measurements from the same participant.'],['A chi-square test of a two-category table','The stated outcome is continuous rather than categorical counts.'],['A correlation coefficient alone as proof of mean change','Strong correlation does not establish a change in the mean.']], 'A paired t test analyzes the set of within-person differences, testing whether their mean differs from the null change. It accounts for pairing rather than pretending two measurements from the same person are independent. The normality assumption concerns the differences, and a causal interpretation still depends on design and comparison conditions.','Choose a paired analysis for repeated continuous observations.',['NIST Engineering Statistics Handbook: Analysis of Paired Observations','https://www.itl.nist.gov/div898/handbook/prc/section3/prc311.htm']),
q(742,S,'Sparse categorical data','application','Recognize that very small expected cell counts undermine a large-sample approximation.','A pilot trial compares a rare binary adverse event between two small independent groups. Several cells in the two-by-two table have very small expected counts. Which test is commonly suitable for an exact association analysis?',[
['Fisher exact test','It can test association in a small contingency table without relying on a large-sample chi-square approximation.'],['Paired t test','This analyzes paired continuous differences rather than independent binary counts.'],['Pearson correlation on four cell totals only','This is not the appropriate exact test of the group-event association.'],['A test requiring all expected counts to be large','The sparse table is the reason that approximation is questionable.']], 'For a sparse two-by-two table, Fisher exact testing evaluates an association under its conditioning assumptions without the usual large-sample chi-square approximation. The test does not make a small trial precise or establish clinical importance. Effect estimates and intervals are still needed alongside a significance result.','Select an appropriate exact approach for sparse binary outcome tables.'),
q(743,S,'Right censoring','integration','Distinguish incomplete observed event time from an observed absence of future events.','A participant leaves a time-to-event study after 18 event-free months and cannot be followed further. How should that observation ordinarily be represented in survival analysis if the censoring assumptions are reasonable?',[
['Right censored at the last known event-free time','The participant contributes observed time without an invented later event time.'],['Recorded as never having the event at any future time','Follow-up cannot establish what happens after contact ends.'],['Assigned an event exactly at dropout','Dropout is not itself proof that the disease event occurred.'],['Deleted along with all prior observation time','The known event-free time can contribute information.']], 'Right censoring records that an event has not occurred by the last observation but its later time is unknown. Standard survival methods can incorporate that information under assumptions about the censoring mechanism. If dropout is related to unmeasured prognosis, ordinary noninformative-censoring assumptions may fail and sensitivity analysis is important.','Represent incomplete follow-up as right censoring rather than an invented outcome.'),
q(744,S,'Hazard ratio','integration','Differentiate an instantaneous rate comparison from a fixed-time risk difference.','A survival model reports a treatment hazard ratio of 0.70 under a reasonable proportional-hazards assumption. Which interpretation is most appropriate?',[
['The modeled instantaneous event rate is lower in the treatment group by about 30%','A hazard ratio compares event rates among those still at risk.'],['Exactly 30% of all participants are saved by treatment','That would require an absolute risk comparison and a defined time horizon.'],['The absolute risk difference is always 0.30 at every time','A hazard ratio does not imply a fixed absolute risk difference.'],['Every treated participant lives 30% longer','A group hazard ratio does not determine individual survival-time gains.']], 'A hazard ratio compares instantaneous event rates among participants who remain event free. Under proportional hazards, the modeled ratio is constant over time, but absolute risks and survival differences still depend on baseline hazard and follow-up. It should not be presented as a guaranteed individual lifespan increase or a fixed absolute benefit.','Interpret a hazard ratio without converting it into an absolute risk or lifespan claim.'),
q(745,S,'Skewed distributions','application','Choose a summary resistant to a small number of extreme high values.','Hospital stay length is strongly right skewed because a few patients remain for many months. Investigators want a measure of the typical central stay that is less affected by these extremes. Which summary is most suitable?',[
['Median with an interquartile range','The median is less sensitive to extreme observations than the mean.'],['Mean alone with no dispersion','A few very long stays can strongly shift the mean.'],['Maximum alone','This describes an extreme rather than a typical patient stay.'],['Variance without a location summary','Dispersion alone does not identify the central stay.']], 'The median locates the middle observation and is relatively robust to extreme values. The interquartile range summarizes the central half of observations. The mean can still be useful for resource planning, so the appropriate summary depends on the question rather than a universal rule that skewed data make means meaningless.','Choose a robust central summary for a strongly right-skewed variable.'),
q(746,S,'Logarithmic outcome scale','integration','Translate an additive change on a log scale into a multiplicative original-scale effect.','A model analyzes the natural logarithm of a biomarker. The estimated treatment coefficient is ln(2), with other model terms held fixed. What multiplicative change in the modeled biomarker scale does exponentiating this coefficient represent?',[
['A factor of two','Exponentiating ln(2) gives the multiplicative ratio two.'],['An increase of exactly 2 units in every patient','A log-scale coefficient is not a fixed additive original-scale increment.'],['A factor of one half','That would correspond to a coefficient of -ln(2).'],['No difference because the coefficient is logarithmic','Transformation does not make a nonzero effect disappear.']], 'A difference on the natural-log scale becomes a ratio after exponentiation. Thus exp(ln2)=2. This describes a modeled multiplicative comparison under the stated model, not a guaranteed doubling of each individual observation. Retranslating means and prediction intervals can require additional assumptions about residual variation.','Interpret exponentiated log-scale coefficients as multiplicative comparisons.'),
q(747,S,'Independent event probabilities','application','Multiply probabilities only after using the stated independence assumption.','Two independent laboratory contamination events each occur with probability 0.10. Under the explicit independence assumption, what is the probability that both occur in the same testing episode?',[
['0.01','For independent events the joint probability is 0.10 multiplied by 0.10.'],['0.20','Adding these probabilities does not give the probability of both events.'],['0.10','The joint event is less likely than either single independent event.'],['0.90','This is the probability that one specified event does not occur.']], 'For independent events, P(A and B)=P(A)P(B)=0.01. The calculation would be inappropriate if shared handling created dependence, so the assumption is essential. This item tests joint probability rather than repeated diagnostic-test updating, where conditional independence must be assessed separately.','Calculate a joint event probability under an explicit independence assumption.'),
q(748,S,'Correlation and causation','integration','Identify an alternative shared cause despite a strong and precise association.','A large study finds a strong correlation between sales of a seasonal cold remedy and respiratory hospital admissions. Both increase during winter. Which conclusion is most defensible from the correlation alone?',[
['A common seasonal driver could explain the association without the remedy causing admissions','Correlation does not identify the causal pathway.'],['The remedy is conclusively harmful in every user','The aggregate association alone does not establish an individual treatment effect.'],['The remedy is conclusively protective','The direction of correlation does not demonstrate protection.'],['A very small p-value removes every alternative explanation','Significance addresses chance under a model, not all causal alternatives.']], 'A strong association can arise because both variables respond to a shared factor such as seasonal infection activity. Precision does not determine causal direction. Individual-level timing, a clear causal design, and attention to confounding are needed before attributing admissions to the remedy rather than to the illness that prompted its use.','Avoid a causal claim from a shared seasonal correlation.'),
q(749,S,'Regression to the mean','integration','Recognize selection on an extreme measurement and random fluctuation at follow-up.','A clinic enrolls people solely because one blood-pressure reading is extremely high. Without any intervention, the average repeat reading is lower. Which phenomenon can contribute even when there is no true treatment effect?',[
['Regression to the mean','Extreme observations partly reflecting random fluctuation tend to be less extreme on repeat measurement.'],['Proof that every participant is cured','A lower group reading does not establish elimination of disease.'],['An inevitable harmful effect of monitoring','The described statistical pattern does not demonstrate harm.'],['A guaranteed systematic calibration change','No device change is necessary for this phenomenon.']], 'Selecting patients because of an extreme measurement enriches the sample for values containing upward random deviations. On repetition, those deviations need not recur, so the average can move toward the underlying distribution. A suitable control group and repeated baseline measurements help distinguish this from a true intervention effect.','Recognize regression to the mean after selection on an extreme baseline.'),
q(750,S,'Absolute versus relative subgroup benefit','synthesis','Combine equal relative effects with different baseline risks and compare absolute treatment benefits.','A treatment halves event risk in both a low-risk group with baseline risk 2% and a high-risk group with baseline risk 20%, over the same period. Harms and costs are otherwise comparable. Which benefit comparison is correct?',[
['Absolute risk reduction is larger in the high-risk group despite the same relative effect','Risks fall by 1 percentage point and 10 percentage points respectively.'],['Both groups necessarily have identical absolute benefit','Equal relative reductions do not imply equal absolute differences.'],['The low-risk group gains a 50-percentage-point reduction','The 50% figure is relative, not an absolute percentage-point change.'],['Baseline risk is irrelevant to treatment decisions','It influences expected absolute benefit and the benefit-harm balance.']], 'Applying the same relative risk of 0.5 gives treated risks of 1% and 10%. Absolute reductions are therefore 1 and 10 percentage points. The higher-risk group may have greater absolute benefit when harms are comparable, but real decisions must also consider adverse effects, competing risks, patient preferences, and applicability of the assumed relative effect.','Compare absolute benefits when equal relative effects act on different baseline risks.'),
q(751,P,'Absolute oral bioavailability','integration','Normalize oral and intravenous exposure by their different administered doses.','In the same patient, an oral dose of 200 mg gives an area under the plasma concentration curve of 80 units. An intravenous dose of 100 mg gives an AUC of 100 units. Assuming linear kinetics and comparable clearance, what is absolute oral bioavailability?',[
['40%','Dose-normalized exposure is (80/200)/(100/100)=0.40.'],['80%','The unadjusted AUC ratio ignores the doubled oral dose.'],['160%','Multiplying by the dose ratio in the wrong direction yields an invalid inference here.'],['50%','The dose ratio alone omits the measured exposure difference.']], 'Absolute bioavailability compares dose-normalized systemic exposure after an extravascular route with intravenous exposure. F=(AUC oral × dose IV)/(AUC IV × dose oral)=0.40. This assumes linear kinetics and comparable clearance; differences in exposure cannot otherwise be assigned entirely to absorption or first-pass loss.','Calculate absolute bioavailability using dose-normalized AUC.',pk),
q(752,P,'First-pass avoidance','application','Identify the route that bypasses portal first-pass delivery rather than changing receptor affinity.','A drug undergoes extensive presystemic hepatic metabolism when swallowed. A rapidly absorbed sublingual formulation produces greater systemic availability without changing the drug molecule. Which explanation is most appropriate?',[
['Sublingual venous absorption largely bypasses initial portal hepatic passage','Avoiding the gastrointestinal portal route can reduce first-pass loss.'],['The formulation necessarily increases intrinsic receptor efficacy','Changing the route does not inherently change molecular receptor efficacy.'],['All subsequent hepatic elimination is permanently prevented','The drug can still be cleared after entering the systemic circulation.'],['The swallowed fraction also bypasses all first-pass metabolism','Any swallowed drug can still enter the gastrointestinal portal pathway.']], 'Drug absorbed through sublingual mucosa enters systemic venous drainage, reducing the initial portal exposure responsible for extensive first-pass loss. This affects bioavailability and onset rather than necessarily altering receptor action. Material that is swallowed and later absorbed through the gut may still undergo presystemic metabolism.','Explain route-dependent availability through avoidance of initial portal metabolism.',pk),
q(753,P,'Clearance from steady infusion','integration','Use a known steady-state input rate and concentration to infer elimination clearance.','A hypothetical drug is infused intravenously at 30 mg/hour. At a stable steady state, its plasma concentration is 5 mg/L. Under linear elimination, what is the estimated total clearance?',[
['6 L/hour','Clearance equals input rate divided by steady-state concentration.'],['150 L/hour','Multiplying rate by concentration does not produce clearance units.'],['0.167 L/hour','This reverses the rate-concentration ratio.'],['25 L/hour','Subtracting the concentration from the rate mixes incompatible units.']], 'At steady state, the input rate equals elimination rate. Under linear kinetics, rate=clearance × concentration, so clearance=30/5=6 L/hour. The result reflects the combined elimination processes active under those conditions. It does not separately identify renal filtration, secretion, or hepatic metabolism.','Infer total clearance from a steady infusion and concentration.',pk),
q(754,P,'Distribution volume interpretation','integration','Infer tissue partitioning from a volume that exceeds actual body water.','After distribution is complete, a drug has an apparent volume of distribution of 500 L in a 70-kg adult. Which interpretation is most defensible?',[
['The drug is concentrated outside plasma through tissue binding or partitioning','Apparent volume is a concentration-based proportionality, not an anatomic fluid compartment.'],['The patient must physically contain 500 L of water','Apparent distribution volume is not a measured body-fluid volume.'],['The drug is confined entirely to plasma','Plasma confinement would produce a much smaller apparent volume.'],['The concentration necessarily equals zero in every tissue','A large apparent volume commonly reflects substantial tissue distribution.']], 'Apparent volume of distribution relates drug amount in the body to measured plasma concentration. Extensive tissue partitioning lowers plasma concentration relative to total amount and can produce a value far greater than body water. The number is a useful pharmacokinetic parameter, not evidence of an anatomical 500-L compartment.','Interpret a large apparent distribution volume as extensive extravascular partitioning.',pk),
q(755,P,'Distribution and dialyzability','prioritization','Integrate tissue distribution with the limited vascular drug pool available to dialysis.','Two toxins have similar molecular size and negligible protein binding. One remains largely in plasma, while the other rapidly partitions into tissues with a very large distribution volume. All else equal, which is generally more accessible to hemodialysis?',[
['The toxin largely confined to plasma','More of its total body amount is available in the vascular compartment for removal.'],['The tissue-bound toxin solely because its distribution volume is larger','A large tissue reservoir can limit immediate extracorporeal removal.'],['Both must be removed equally because molecular size is equal','Distribution also matters in addition to membrane passage.'],['Neither can ever be removed because no drug is protein bound','Low protein binding can favor, rather than forbid, dialysis access.']], 'Hemodialysis removes substances from blood, so accessible intravascular amount and redistribution influence overall removal. A toxin with a small distribution volume is often more amenable than one sequestered in tissues, assuming other properties are similar. Real decisions also depend on endogenous clearance, toxicity, dialysis characteristics, and available evidence.','Use distribution volume when assessing potential extracorporeal toxin removal.',pk),
q(756,P,'Free versus total drug concentration','prioritization','Interpret binding changes before increasing a dose based on a low total concentration.','A patient with severe hypoalbuminemia takes a highly albumin-bound drug. The measured total concentration is low, but an unbound concentration is within the therapeutic range and clinical effect is adequate. Which response is best justified by these data?',[
['Avoid increasing the dose solely to normalize the total concentration','Reduced binding can lower total concentration while active unbound exposure remains adequate.'],['Double the dose automatically because total concentration is low','This may raise active exposure and toxicity despite adequate unbound levels.'],['Assume the unbound measurement is irrelevant to effect','Unbound drug is often the fraction available for distribution and action.'],['Conclude that every protein-bound drug is completely inactive forever','Binding is generally reversible and participates in distribution dynamics.']], 'Total concentration includes bound and unbound drug. A binding change can alter the relationship between total measured concentration and pharmacologically available exposure. When a reliable unbound value and clinical assessment indicate adequate exposure, chasing the total reference range can be harmful. Interpretation remains drug specific and must account for clearance and sampling timing.','Interpret therapeutic exposure using unbound concentration when protein binding is altered.',pk),
q(757,P,'Time to steady state','application','Separate the time constant from the height of the eventual plateau.','A drug with linear kinetics is given by continuous infusion. Investigators double the infusion rate without changing clearance or distribution volume. What happens to the time required to reach the same fraction of the new steady-state concentration?',[
['It remains approximately unchanged','The approach fraction is determined by the elimination time constant under linear kinetics.'],['It is necessarily halved','Doubling input raises the plateau but does not halve the elimination half-life.'],['It doubles because the target concentration doubles','The fractional approach depends on rate constant rather than absolute plateau height.'],['Steady state becomes impossible at any nonzero infusion','Linear elimination can balance a constant input.']], 'With linear kinetics, half-life depends on clearance and distribution volume, not infusion rate. Increasing the rate changes the steady-state concentration but not the time needed to reach a specified fraction of it. This distinction fails if concentrations enter a range with saturable or otherwise nonlinear clearance.','Distinguish dose-dependent plateau concentration from the linear time to steady state.',pk),
q(758,P,'Saturable elimination','integration','Recognize loss of proportional concentration response when metabolism approaches capacity.','A patient takes a drug whose metabolic enzymes are near capacity. A small increase in daily dose produces a disproportionately large rise in plasma concentration. Which kinetic explanation best fits?',[
['Capacity-limited elimination','As metabolic pathways saturate, clearance can fall and exposure rises nonlinearly.'],['Unchanged first-order clearance across all concentrations','That would usually yield a proportional rather than disproportionate exposure change.'],['An increase in elimination capacity exactly matching the dose increase','This would not explain accumulation out of proportion to dose.'],['Complete cessation of drug absorption','Reduced absorption would not account for the marked concentration increase.']], 'When elimination pathways approach their maximum capacity, an increase in dose may not be matched by a proportional increase in elimination. Apparent clearance falls as concentration rises, and accumulation can become nonlinear. Dose adjustments therefore require attention to the specific drug, measured exposure, and clinical response rather than assuming proportionality.','Recognize nonlinear accumulation near a saturable metabolic capacity.',pk),
q(759,P,'Zero-order elimination','application','Identify a constant amount removed per unit time rather than a constant fraction.','Over a concentration range where elimination is saturated, a hypothetical drug amount in the body falls from 100 mg to 80 mg in one hour and then to 60 mg in the next. Which description best fits?',[
['Approximately zero-order elimination over that range','A constant amount of 20 mg is removed each hour.'],['First-order elimination with a constant fractional decrease','The fractions removed are different as the amount declines.'],['A fixed one-hour half-life','Neither hour halves the starting amount.'],['No elimination occurs','The amount falls substantially during both intervals.']], 'Zero-order elimination removes an approximately constant amount per unit time when a process is capacity limited. A fixed half-life cannot be applied across that range because the time to remove half depends on the starting amount. As concentration falls below saturation, kinetics may become more nearly first order.','Distinguish constant-amount elimination from a constant half-life.',pk),
q(760,P,'Weak acid ion trapping','integration','Apply ionization and membrane permeability to the direction of renal reabsorption.','In a simplified renal model, a weak acid is filtered and can diffuse back across the tubular epithelium only when nonionized. Raising urine pH increases its ionized fraction. What happens to passive tubular reabsorption?',[
['It decreases','The ionized form crosses lipid membranes less readily and remains in tubular fluid.'],['It necessarily increases','Greater ionization opposes passive diffusion of this weak acid.'],['It becomes active secretion by definition','Ionization-driven trapping is distinct from transporter-mediated secretion.'],['Glomerular filtration must stop','Changing passive reabsorption does not require cessation of filtration.']], 'For a weak acid, a more alkaline environment favors the charged form. In the specified model, that form diffuses poorly across the tubular membrane, reducing reabsorption and favoring urinary elimination. Applying this principle clinically requires drug-specific evidence and monitoring; not every poisoning is safely managed by changing urine pH.','Explain reduced weak-acid reabsorption through urinary ion trapping.',pk),
q(761,P,'Weak base acidic compartment','integration','Reverse the weak-acid rule and connect protonation to trapping in an acidic compartment.','A lipophilic weak base crosses a membrane in its uncharged form and enters an acidic intracellular compartment. Protonation produces a charged form that crosses poorly. Which distribution pattern is expected?',[
['Accumulation in the acidic compartment','Protonation reduces escape and can produce ion trapping.'],['Immediate exclusion from every acidic compartment','The uncharged form can enter before being protonated.'],['Permanent conversion into a strong acid','Protonation changes charge state rather than the drug chemical identity this way.'],['No role for compartment pH','Ionization and membrane movement explicitly depend on pH in the model.']], 'A weak base can diffuse into a compartment while uncharged and become protonated in the more acidic environment. The charged form leaves less readily, producing accumulation. The principle concerns equilibrium distribution and does not by itself prove therapeutic efficacy or toxicity in a specific organ.','Predict acidic-compartment trapping of a permeant weak base.',pk),
q(762,P,'Flow-limited hepatic clearance','integration','Identify which variable dominates when extraction is already very high.','A drug is almost completely extracted from blood during each passage through the liver. Protein binding and intrinsic metabolic capacity remain sufficient. A sudden reduction in hepatic blood flow would most directly cause which change?',[
['Reduced hepatic clearance','For a high-extraction drug, delivery of drug to the liver can limit clearance.'],['Proportional increase in hepatic clearance','Less delivery does not increase removal per unit time in this model.'],['No possible effect because extraction is high','High extraction makes clearance sensitive to organ blood flow.'],['Complete elimination of all extrahepatic clearance by definition','Hepatic extraction does not define every other elimination route.']], 'For a high-extraction drug, the liver removes most arriving drug, so clearance can approach hepatic blood flow. Reducing flow reduces the amount presented for removal per unit time. This differs from low-extraction drugs, for which intrinsic capacity and unbound fraction can be more influential under standard models.','Recognize blood-flow dependence of high-extraction hepatic clearance.',pk),
q(763,P,'Poor metabolizer prodrug','integration','Distinguish impaired activation of a prodrug from reduced elimination of an active parent.','A prodrug requires a particular enzyme to form its principal active metabolite. A patient has very low activity of that enzyme and no alternative activating pathway. Which response is most likely at the same administered dose?',[
['Reduced active metabolite exposure and reduced effect','Impaired biotransformation can limit activation despite adequate parent drug delivery.'],['Necessarily increased therapeutic effect from all parent accumulation','The parent is a prodrug and cannot simply be assumed to provide the active effect.'],['Unchanged activation regardless of genotype','The activating step is explicitly enzyme dependent.'],['A change in receptor number is required to explain the result','Altered activation can change effect without receptor adaptation.']], 'Reduced enzyme activity has different consequences depending on whether metabolism inactivates a parent drug or activates a prodrug. Here the required active metabolite is formed less efficiently, so effect may fall. This mechanistic distinction is essential when interpreting pharmacogenetic or drug-interaction data; a generic rule that slower metabolism always increases effect is incorrect.','Interpret reduced enzyme activity when metabolism activates a prodrug.',interaction),
q(764,P,'Enzyme induction time course','integration','Relate delayed interaction onset and offset to protein synthesis and enzyme turnover.','A patient starts a drug that induces metabolic enzyme expression. The interacting effect develops over several days rather than immediately and persists briefly after the inducer is stopped. Which explanation best fits?',[
['Enzyme abundance changes through synthesis and turnover','Induction and subsequent loss of extra enzyme activity can take time.'],['The inducer must instantly destroy every enzyme molecule','Destruction would not explain increased metabolic capacity.'],['All induction is a direct competitive effect lasting only seconds','Gene-expression-mediated induction has a different time course.'],['The drug must irreversibly bind the clinical target receptor','An enzyme-expression interaction does not require that receptor mechanism.']], 'Induction often requires transcriptional responses and synthesis of additional metabolic proteins. After the inducer is removed, the excess enzyme pool declines with turnover rather than disappearing instantly. The timing matters for monitoring coadministered drugs and differs from the rapid onset of many direct inhibitory interactions.','Explain delayed induction and deinduction through enzyme turnover.',interaction),
q(765,P,'Intestinal efflux transport','integration','Separate a transporter-mediated absorption barrier from hepatic metabolism.','A drug is a substrate of an intestinal efflux transporter that returns absorbed molecules toward the gut lumen. A selective inhibitor blocks the transporter without affecting metabolism. Which change is most plausible?',[
['Increased oral systemic exposure if efflux was limiting absorption','Less drug is pumped back toward the lumen.'],['A required reduction in receptor affinity','Transport inhibition need not change receptor binding.'],['Complete prevention of all renal excretion','The stated inhibitor acts on intestinal transport, not every excretory route.'],['Reduced exposure in every substrate regardless of competing processes','The direction and magnitude depend on the transport and other pharmacokinetic pathways.']], 'Intestinal efflux transport can limit net absorption of substrate drugs. Blocking that pathway may increase oral exposure even without enzyme inhibition. Clinical interactions can involve several transporters and enzymes at once, so a mechanistic model should not be generalized to all drugs without checking the specific interaction.','Distinguish intestinal efflux inhibition from metabolic inhibition.',interaction),
q(766,P,'Grapefruit interaction specificity','prioritization','Apply an identified intestinal enzyme interaction without treating all members of a drug class identically.','A patient taking simvastatin begins drinking large quantities of grapefruit juice and develops muscle symptoms. Which explanation is consistent with the documented interaction?',[
['Inhibition of intestinal CYP3A4 can increase exposure to susceptible drugs','The interaction is drug specific and can increase some statin concentrations.'],['Grapefruit uniformly lowers every statin concentration','The direction and relevance vary by drug; this is not a universal class effect.'],['Grapefruit necessarily eliminates all hepatic metabolism forever','The described interaction does not abolish every metabolic pathway.'],['Fruit juice always prevents absorption of every medication','Some interactions increase exposure while others differ.']], 'Grapefruit can inhibit intestinal CYP3A4, increasing exposure to drugs that depend on this presystemic metabolism. FDA identifies simvastatin among relevant examples. Not all statins or all fruit-drug interactions behave the same way, so counseling should follow the exact product and concurrent medications rather than a universal rule.','Identify drug-specific exposure elevation from grapefruit-mediated intestinal CYP3A4 inhibition.',['FDA: Grapefruit Juice and Some Drugs Do Not Mix','https://www.fda.gov/consumers/consumer-updates/grapefruit-juice-and-some-drugs-dont-mix']),
q(767,P,'Smoking-related enzyme induction','prioritization','Distinguish combustion exposure changes from nicotine substitution when assessing an interaction.','A smoker taking a CYP1A2 substrate with a narrow therapeutic range stops smoking during admission. The team is concerned about loss of smoke-related enzyme induction. What is the pharmacokinetic concern if other factors are unchanged?',[
['Drug exposure may rise as induction wanes','Reduced metabolic capacity can increase concentrations of a susceptible active substrate.'],['Every affected drug concentration must fall','Loss of induction commonly decreases clearance rather than increases it.'],['Nicotine replacement necessarily reproduces every effect of smoke combustion products','The relevant inducing exposure is not interchangeable with nicotine alone.'],['Only oral absorption can change after smoking stops','Metabolic enzyme activity can also change.']], 'Tobacco smoke can induce selected drug-metabolizing enzymes, including CYP1A2. Stopping the inducing exposure may raise concentrations of susceptible active drugs as induction resolves. The interaction requires product-specific assessment and monitoring; a smoking change is not a reason to make the same automatic dose adjustment for every medication.','Recognize concentration changes after cessation of smoke-related enzyme induction.',interaction),
q(768,P,'Enterohepatic recycling','integration','Trace biliary secretion, intestinal release and reabsorption as a recycling pathway.','A drug is conjugated in the liver and excreted into bile. Intestinal processes regenerate an absorbable form, producing a later plasma concentration peak. Which process best explains this delayed return?',[
['Enterohepatic recycling','Biliary delivery followed by intestinal reabsorption returns drug to circulation.'],['A new intravenous dose that was not administered','A later peak can occur without another administered dose.'],['Complete absence of any hepatic processing','The stem explicitly includes hepatic conjugation and biliary secretion.'],['Irreversible destruction of every conjugated molecule','Regeneration and reabsorption require some recoverable drug form.']], 'Enterohepatic recycling links biliary excretion to intestinal reabsorption of a drug or regenerated active form. It can prolong exposure or create secondary concentration peaks. The magnitude depends on the molecule and intestinal processes, so the pattern should be distinguished from delayed formulation release or an unrecorded additional dose.','Identify enterohepatic recycling as a cause of secondary drug exposure peaks.',pk),
q(769,P,'Redistribution after bolus','integration','Separate rapid loss of central effect from complete metabolic elimination.','A highly lipid-soluble sedative produces rapid hypnosis after one intravenous bolus. The patient awakens while much of the administered drug remains elsewhere in the body. Which process can account for the short initial effect?',[
['Redistribution from brain to other tissues','Declining brain concentration can terminate hypnosis before the body eliminates all drug.'],['Complete renal excretion within seconds is obligatory','Rapid awakening does not require complete elimination.'],['Permanent loss of every sedative receptor','The effect can end through concentration changes without receptor destruction.'],['A requirement for absent tissue perfusion','Redistribution depends on distribution between perfused compartments.']], 'After an intravenous bolus, a lipid-soluble drug can reach the brain quickly and then redistribute to muscle and other tissues. Falling effect-site concentration can end the initial effect even while total body drug persists. Repeated dosing may saturate reservoirs and prolong recovery, so single-bolus duration cannot be assumed to describe a long infusion.','Distinguish redistribution-limited initial effect from whole-body elimination.',pk),
q(770,P,'Modified-release formulation integrity','prioritization','Connect a dosage-form change to release kinetics rather than assuming chemical equivalence is enough.','A patient has difficulty swallowing a modified-release tablet. A caregiver proposes crushing it to simplify administration. Why should the exact product instructions be checked before doing this?',[
['Crushing can disrupt controlled release and cause rapid delivery of a larger amount','Dosage-form design can be essential to safe exposure over time.'],['All tablets are pharmacokinetically identical after crushing','Release properties and coatings can materially change exposure.'],['Crushing necessarily makes every drug inactive','The problem can be accelerated release rather than loss of all activity.'],['The prescribed total daily dose guarantees an unchanged peak','The same total dose can yield different peak concentrations when release changes.']], 'Modified-release products use formulation features to control when and how quickly drug is delivered. Disrupting them can cause dose dumping or loss of intended delivery behavior. Some products permit specific administration alternatives, so the answer is to verify the exact formulation rather than applying one crushing rule to every medication.','Protect modified-release kinetics by checking product-specific administration instructions.',pharm),
q(771,P,'Dosing interval and fluctuation','integration','Hold average input constant while predicting larger peak-trough differences with less frequent dosing.','Under linear kinetics, two regimens give the same total daily amount of an immediate-release drug. One uses larger doses at longer intervals. Assuming similar bioavailability, what is most likely with the less frequent regimen?',[
['Greater peak-trough fluctuation despite a similar average exposure','Larger intermittent inputs separate high post-dose and low pre-dose concentrations.'],['Identical concentration-time curves at every moment','Equal daily amounts do not guarantee identical peaks and troughs.'],['A necessary increase in average clearance','The schedule alone does not change the assumed linear clearance.'],['No trough can occur when the daily amount is unchanged','Concentration can fall between larger, less frequent doses.']], 'For a linearly eliminated drug, average steady-state exposure depends on average dosing rate and clearance, while the interval and dose size shape fluctuations. Larger doses farther apart can raise peaks and lower troughs. Whether that is acceptable depends on concentration-effect relationships, toxicity, and pharmacodynamic duration rather than daily total alone.','Distinguish average drug exposure from dosing-interval peak-trough variation.',pk),
q(772,P,'Therapeutic index','application','Compare effective and toxic dose ranges rather than confusing potency with safety margin.','Drug A and drug B have similar clinical efficacy, but toxic responses occur close to effective doses for A and far above them for B. Which description best applies to drug A?',[
['A narrower therapeutic index','The effective and toxic ranges are less widely separated.'],['Necessarily greater maximal efficacy','Safety margin does not itself determine maximal therapeutic effect.'],['Guaranteed lower receptor affinity','Therapeutic separation does not uniquely specify binding affinity.'],['No possible therapeutic use','Narrow-index drugs can be useful with appropriate selection and monitoring.']], 'Therapeutic index describes separation between effective and toxic dose ranges in a defined model. A narrow index means smaller exposure changes may cross into toxicity. It does not directly measure potency or efficacy, and real patient variability means monitoring and context can matter beyond a single population ratio.','Interpret a narrow therapeutic index as limited separation of benefit and toxicity.',pharm),
q(773,P,'Irreversible antagonist','integration','Infer reduced maximal capacity when receptor inactivation cannot be overcome by added agonist.','In a preparation with no substantial spare receptors, a compound irreversibly inactivates half of a receptor population. Increasing agonist concentration cannot restore the original maximum response. Which explanation fits?',[
['Reduced available receptor capacity lowers maximal response','Irreversible blockade cannot be displaced by additional agonist at occupied receptors.'],['A simple reversible competitive shift only','Pure surmountable competition generally preserves the attainable maximum in a simple system.'],['An increase in receptor number','The experiment removes rather than adds functional receptors.'],['Greater intrinsic efficacy of the antagonist','An antagonist does not produce this effect through increased agonist efficacy.']], 'Irreversible antagonism reduces functional receptor availability. Without spare receptors, this can lower the maximum response even at high agonist concentration. The explicit absence of substantial receptor reserve matters because spare receptors can initially mask a reduction in receptor number. This differs from a purely reversible competitive right shift.','Interpret reduced maximal response after irreversible receptor inactivation.',pharm),
q(774,P,'Potency versus efficacy','integration','Compare horizontal dose-response displacement separately from the maximal effect.','Two full agonists produce the same maximum response in one tissue. Drug A reaches half of that maximum at a lower concentration than drug B. Which comparison is justified?',[
['A is more potent, with similar maximal efficacy in this system','Lower EC50 reflects greater potency while the maxima are equal.'],['A must have a higher maximal efficacy','The experiment states equal maximum responses.'],['B is more potent because more drug is required','Requiring a higher concentration indicates lower potency in this comparison.'],['A is necessarily safer for all patients','Potency alone does not establish therapeutic safety.']], 'Potency describes the concentration or dose needed for a specified effect, while efficacy describes the attainable response in the system. A lower EC50 with the same maximum indicates greater potency, not greater maximum efficacy. Clinical choice also depends on kinetics, safety, selectivity and patient factors rather than dose size alone.','Distinguish EC50-defined potency from maximal efficacy.',pharm),
q(775,P,'Spare receptors','integration','Recognize maximal signaling despite incomplete receptor occupancy.','In a tissue preparation, an agonist produces its maximum measured effect while occupying only 20% of receptors. Which concept explains the difference between occupancy and response?',[
['Receptor reserve with downstream signal amplification','A maximal tissue response can occur without occupancy of every receptor.'],['Every unoccupied receptor must be permanently nonfunctional','Unoccupied receptors can remain available even when the response is maximal.'],['The agonist has zero intrinsic efficacy','A substantial response is incompatible with no signaling ability in this system.'],['Receptor occupancy and tissue response must always be identical percentages','Signal transduction can make the relationship nonlinear.']], 'Spare receptors exist when maximal effect is reached before full receptor occupancy, often because downstream signaling amplifies receptor activation. This helps explain why receptor affinity and measured EC50 need not coincide and why partial receptor loss may initially leave the maximum response intact. The amount of reserve is system and response dependent.','Explain maximal effect at partial receptor occupancy through receptor reserve.',pharm),
q(776,P,'Inverse agonism','integration','Compare baseline constitutive activity with the effects of two receptor-binding ligands.','A receptor has measurable activity without ligand. One compound blocks an agonist but leaves baseline activity unchanged; another lowers signaling below baseline. How is the second compound best classified?',[
['Inverse agonist','It reduces constitutive receptor activity below the ligand-free baseline.'],['Neutral antagonist','A neutral antagonist blocks agonist binding without reducing baseline constitutive activity.'],['Full agonist','A full agonist increases rather than suppresses signaling in this model.'],['Positive allosteric modulator','This generally enhances agonist-related signaling rather than defining below-baseline suppression.']], 'An inverse agonist stabilizes receptor states associated with less signaling and can reduce constitutive activity. A neutral antagonist can oppose an agonist without changing that baseline. The distinction requires a system with detectable constitutive activity; simply observing reduced response to an added agonist does not prove inverse agonism.','Distinguish inverse agonism from neutral receptor antagonism.',pharm),
q(777,P,'Physiologic antagonism','application','Recognize opposite effects mediated through different receptors rather than competitive binding.','Histamine contracts a bronchial preparation through one receptor system. A beta-2 agonist relaxes the same preparation through a different receptor. Which term best describes opposition through these separate signaling systems?',[
['Physiologic antagonism','Different receptors produce opposing functional effects in the same tissue.'],['Competitive antagonism at the histamine binding site','The beta-2 agonist is not described as occupying the histamine receptor.'],['Irreversible histamine receptor destruction','No receptor inactivation is required for the opposing effect.'],['Chemical neutralization in solution','The opposition is mediated by tissue signaling rather than direct chemical binding.']], 'Physiologic antagonism occurs when separate receptor pathways produce opposing effects, such as contraction and relaxation. It differs from a competitive antagonist that competes at the same receptor and from a chemical antagonist that directly neutralizes another substance. Functional opposition does not imply that all consequences of the first mediator are blocked.','Recognize opposing tissue responses mediated through different receptor systems.',pharm),
q(778,P,'Chemical antagonism','application','Identify direct binding neutralization as distinct from receptor competition or enzyme induction.','A positively charged antidote binds a negatively charged anticoagulant, forming an inactive complex. The interaction does not require occupancy of the anticoagulant target enzyme. Which mechanism is illustrated?',[
['Chemical antagonism','Direct molecular binding neutralizes the active substance.'],['Reversible competition at a shared receptor','The stem describes a binding complex between substances rather than a common receptor.'],['Metabolic enzyme induction','New enzyme synthesis is not the immediate neutralizing process.'],['Receptor downregulation','The effect does not depend on reducing receptor number.']], 'Direct binding between an antidote and a drug can reduce the free active amount through chemical antagonism. This differs from blocking the drug at a receptor or accelerating its metabolism. The effectiveness and dosing of a real antidote still depend on the exact drug, exposure, and possible adverse effects; the mechanism alone is not a prescribing instruction.','Identify direct drug-antidote complex formation as chemical antagonism.',pharm),
q(779,P,'Receptor desensitization','integration','Connect a declining response at unchanged concentration to altered signaling rather than changed clearance.','During continuous agonist exposure, a cell preparation has a stable extracellular drug concentration but progressively weaker signaling. Receptor phosphorylation and internalization are detected. Which mechanism best accounts for the decline?',[
['Receptor desensitization and reduced surface availability','Adaptation can reduce signaling despite unchanged drug concentration.'],['Accelerated systemic renal clearance','An isolated cell preparation with stable exposure does not require this explanation.'],['An increase in the agonist maximal efficacy','The observed response is falling rather than increasing.'],['A required conversion to irreversible receptor activation','Internalization and reduced response do not imply permanent activation.']], 'Continuous stimulation can trigger phosphorylation, altered coupling, and receptor internalization, reducing the response to an unchanged agonist concentration. This is pharmacodynamic adaptation rather than necessarily a change in pharmacokinetic exposure. The time course and mechanisms vary by receptor and should not be generalized to every form of tolerance.','Distinguish receptor adaptation from falling drug exposure.',pharm),
q(780,P,'Drug concentration sampling time','prioritization','Account for a post-dose distribution phase before interpreting an apparent toxic result.','A drug concentration is drawn immediately after an intravenous dose, before distribution equilibrium. It exceeds a reference range intended for a later standardized sample. The patient has no toxicity signs. What is the most appropriate interpretation?',[
['The result may be incomparable to the intended reference because sampling timing differs','A transient early plasma peak can precede distribution into tissues.'],['Any above-range early sample proves established tissue toxicity','The reference timing and clinical context must be considered.'],['Sampling time never affects therapeutic interpretation','Concentrations vary substantially across the dosing interval and distribution phase.'],['The administered dose must have been zero','A high early level is not evidence that no drug was given.']], 'Therapeutic concentration ranges are meaningful only with an appropriate sampling context, including time since dose and whether distribution or steady state has been reached. An early post-dose peak cannot automatically be compared with a later standardized target. Clinical assessment and drug-specific monitoring guidance should determine whether repeat sampling or action is needed.','Interpret drug monitoring results using the intended sampling time.',pk),
q(781,P,'HMG-CoA reductase inhibition','integration','Link a hepatic synthesis block to compensatory receptor-mediated clearance of circulating LDL.','A lipid-lowering drug inhibits hepatic HMG-CoA reductase. Hepatocytes respond to lower intracellular cholesterol by increasing LDL receptor expression. Which change most directly lowers circulating LDL?',[
['Increased receptor-mediated hepatic LDL uptake','More surface LDL receptors accelerate removal of LDL particles from plasma.'],['Direct lysis of every circulating lipoprotein','The drug does not lower LDL through nonspecific particle destruction.'],['Inhibition of pancreatic triglyceride digestion alone','That does not describe the stated hepatic feedback pathway.'],['Blockade of all hepatic LDL receptors','Reducing receptor-mediated uptake would oppose the described effect.']], 'Statin inhibition of cholesterol synthesis lowers the hepatocyte regulatory cholesterol pool and promotes LDL receptor expression. Increased hepatic uptake then reduces circulating LDL. This mechanistic item is distinct from age-based treatment indications; the appropriate drug and intensity still depend on the clinical setting and current recommendations.','Explain statin LDL lowering through compensatory hepatic LDL receptor upregulation.',pharm),
q(782,P,'PCSK9 and LDL receptors','integration','Trace preservation of receptor recycling rather than inhibition of cholesterol synthesis.','A monoclonal antibody blocks PCSK9 and lowers LDL cholesterol. Which effect most directly accounts for improved hepatic LDL removal?',[
['Reduced LDL receptor degradation with greater receptor recycling','Preserved receptors can return to the cell surface and clear additional LDL.'],['Direct inhibition of HMG-CoA reductase','That is the principal statin target rather than the PCSK9 antibody mechanism.'],['Inhibition of intestinal NPC1L1','That is associated with ezetimibe, not PCSK9 blockade.'],['Activation of platelet P2Y12 receptors','This does not explain LDL receptor availability.']], 'PCSK9 promotes degradation of LDL receptors after internalization. Blocking it preserves receptor recycling and increases receptor availability at the hepatocyte surface. The pathway complements but differs from synthesis inhibition and intestinal absorption inhibition. This explanation identifies mechanism without claiming that every patient requires this class.','Distinguish PCSK9 blockade from other lipid-lowering targets.',pharm),
q(783,P,'Intestinal cholesterol uptake','application','Identify a luminal uptake target rather than the hepatic synthesis enzyme.','A patient receives ezetimibe in addition to an established lipid regimen. Which target most directly mediates its cholesterol-lowering action?',[
['NPC1L1-mediated intestinal cholesterol uptake','Blocking this pathway reduces entry of absorbed cholesterol into the body.'],['Hepatic HMG-CoA reductase','That enzyme is the primary statin target.'],['Renal sodium-glucose cotransporter 2','This is a glucose-handling target rather than the ezetimibe mechanism.'],['Platelet cyclooxygenase 1','That is the principal low-dose aspirin antiplatelet target.']], 'Ezetimibe inhibits NPC1L1-associated intestinal cholesterol absorption. Lower delivery of absorbed cholesterol to the liver contributes to reduced circulating LDL, particularly when used with another suitable therapy. It does not principally inhibit hepatic HMG-CoA reductase, so the two classes act at different points in cholesterol handling.','Identify ezetimibe as an inhibitor of intestinal NPC1L1-mediated cholesterol uptake.',pharm),
q(784,P,'Bile acid binding','integration','Connect interrupted recycling with hepatic use of cholesterol to replace bile acids.','A nonabsorbed resin binds intestinal bile acids and increases their fecal loss. Which hepatic response contributes to lowering LDL cholesterol?',[
['Increased use of cholesterol for replacement bile acid synthesis','Depletion of the hepatic pool can promote LDL receptor-mediated uptake.'],['Direct synthesis of additional cholesterol in the intestinal lumen','The resin does not create a new luminal synthesis pathway.'],['Complete inhibition of every lipoprotein receptor','Reduced hepatic LDL uptake would oppose the desired effect.'],['Direct blockade of cardiac beta receptors','This does not explain the intestinal binding and hepatic response.']], 'Bile acid sequestrants reduce enterohepatic reclamation, requiring hepatic synthesis of new bile acids from cholesterol. This can reduce the regulatory hepatic cholesterol pool and favor LDL receptor activity. The agents can also affect absorption of other medications and may raise triglycerides, so their suitability is context dependent.','Explain LDL lowering after interruption of bile acid recycling.',pharm),
q(785,P,'Xanthine oxidase drug interaction','prioritization','Recognize impaired inactivation of a thiopurine when a second drug blocks its metabolic route.','A patient taking azathioprine is prescribed allopurinol. The team recognizes that xanthine oxidase participates in thiopurine metabolite inactivation. Which consequence requires a coordinated drug-specific prescribing review?',[
['Increased thiopurine toxicity risk from impaired inactivation','The interaction can increase active thiopurine exposure and marrow toxicity.'],['Guaranteed loss of all immunosuppressive effect','Blocking an inactivation pathway can increase rather than eliminate exposure.'],['A purely mechanical reduction in tablet swallowing','The concern is metabolic rather than physical tablet administration.'],['A universal instruction to double azathioprine','That would worsen the potential toxicity rather than address it.']], 'Azathioprine generates thiopurine metabolites, some of which are inactivated through xanthine oxidase-related pathways. Inhibiting that pathway with allopurinol can increase toxicity unless a deliberately managed regimen accounts for the interaction. This is not an automatic dose rule: specialist guidance and monitoring are needed for the exact clinical context.','Recognize the clinically important allopurinol-thiopurine interaction.',pharm),
q(786,P,'Methotrexate and folate metabolism','integration','Link inhibited folate regeneration to nucleotide synthesis rather than mitochondrial energy production.','A rapidly dividing cell is exposed to methotrexate at a concentration that inhibits dihydrofolate reductase. Which downstream process is most directly limited by reduced tetrahydrofolate availability?',[
['Synthesis of thymidylate and purine nucleotides','Reduced folate cofactor availability impairs one-carbon transfer needed for nucleotide production.'],['Hydrolysis of dietary triglycerides','This is a digestive enzyme function rather than a folate-dependent pathway.'],['Reduction of oxygen at respiratory complex IV','This is not the direct folate-linked nucleotide synthesis process.'],['Renal glucose transport through SGLT2','That membrane transporter does not require DHFR-mediated folate regeneration in this way.']], 'Dihydrofolate reductase regenerates reduced folate cofactors used in one-carbon reactions. Inhibition can restrict thymidylate and purine synthesis, particularly affecting proliferating cells. Methotrexate has additional context-dependent anti-inflammatory mechanisms, so the stated enzyme-level model should not be presented as the sole explanation for every low-dose clinical effect.','Connect DHFR inhibition to reduced folate-dependent nucleotide synthesis.',pharm),
q(787,P,'Leucovorin rescue','integration','Distinguish bypassing a blocked activation step from simply adding its precursor.','After a planned high-dose methotrexate regimen, a reduced folate preparation is used according to a monitored rescue protocol. Why can leucovorin support normal-cell folate function despite DHFR inhibition?',[
['It supplies a reduced folate form that bypasses the blocked reduction step','The rescue does not require ordinary folic acid to pass through the same DHFR bottleneck.'],['It increases methotrexate binding to every normal-cell receptor','That would not explain rescue of folate-dependent processes.'],['It is chemically identical to inactive extracellular methotrexate','Leucovorin is a folate derivative, not the same drug.'],['It eliminates the need for drug-level or renal monitoring','Rescue protocols still require careful timing and monitoring.']], 'Leucovorin provides a reduced folate source downstream of the DHFR-dependent step, supporting nucleotide synthesis in susceptible normal tissues. The benefit depends on timing and protocol; it should not be interpreted as permission to ignore delayed methotrexate clearance or renal injury. This differs from merely replacing ordinary dietary folic acid in the high-dose rescue setting.','Explain reduced-folate rescue as bypass of a DHFR-dependent bottleneck.',pharm),
q(788,P,'Calcineurin inhibition','integration','Link a drug target to T-cell transcription rather than DNA synthesis alone.','A transplant drug binds an intracellular immunophilin and inhibits calcineurin. Which immune change most directly follows the blockade of this phosphatase pathway?',[
['Reduced activation of NFAT-dependent interleukin-2 transcription','Calcineurin signaling supports T-cell activation and cytokine expression.'],['Direct inhibition of bacterial peptidoglycan cross-linking','This is an antibacterial wall target rather than T-cell signaling.'],['Increased activation of every resting T cell','The intervention suppresses rather than universally enhances this pathway.'],['Immediate destruction of all circulating immunoglobulin','Calcineurin blockade is not direct antibody removal.']], 'Calcineurin normally promotes NFAT-dependent transcription after T-cell receptor calcium signaling. Inhibiting it reduces cytokine signaling important for T-cell activation. The mechanism differs from antimetabolites and antibodies that target other immune components, while clinical use requires monitoring for renal and other adverse effects.','Identify reduced NFAT/IL-2 signaling after calcineurin inhibition.',pharm),
q(789,P,'mTOR inhibition','integration','Differentiate suppression of cytokine-response signaling from suppression of cytokine transcription.','A drug-immunophilin complex inhibits mTOR rather than calcineurin. Which effect best distinguishes this pathway from calcineurin-mediated inhibition of IL-2 transcription?',[
['Reduced cellular proliferative response to growth signals','mTOR inhibition acts on signaling governing cell growth and proliferation.'],['Direct restoration of all calcineurin activity','The drug acts through a distinct target rather than reversing another inhibitor.'],['Selective destruction of bacterial ribosomal RNA','This is not the mammalian mTOR pathway.'],['Mandatory increased T-cell proliferation','The intended effect is inhibition of a growth-related signaling pathway.']], 'mTOR integrates growth and nutrient signals supporting cell-cycle progression and proliferation. Agents targeting this pathway can inhibit immune-cell responses downstream of growth signals, distinguishing them from calcineurin inhibitors that reduce NFAT-related cytokine transcription. Shared immunophilin binding does not mean that the final molecular target is the same.','Distinguish mTOR-dependent growth signaling from calcineurin-dependent cytokine transcription.',pharm),
q(790,P,'P2Y12 inhibition','application','Identify an ADP-linked platelet pathway rather than the coagulation cascade.','A patient receives a drug that inhibits platelet P2Y12 receptors. Which signaling response is most directly reduced?',[
['ADP-mediated platelet activation and aggregation','P2Y12 is an important platelet ADP receptor.'],['Vitamin K recycling in hepatocytes','This is the warfarin target rather than platelet P2Y12.'],['Antithrombin potentiation','This is associated with heparin rather than the receptor blocker.'],['Direct conversion of plasminogen into plasmin','This describes a fibrinolytic pathway, not ADP receptor inhibition.']], 'P2Y12 receptor signaling helps amplify platelet activation in response to ADP. Inhibiting it reduces platelet aggregation, acting at a different level from coagulation-factor inhibitors or fibrinolytics. The shared goal of preventing thrombosis does not make these drug classes mechanistically interchangeable or give them identical bleeding and clinical-use profiles.','Locate P2Y12 drug action at platelet ADP signaling.',pharm),
q(791,P,'Proton pump inhibition','integration','Locate the final acid secretory step rather than an upstream histamine receptor.','A drug irreversibly inhibits the gastric parietal-cell H/K ATPase. Which effect most directly accounts for acid suppression?',[
['Blockade of the final proton secretion step into the gastric lumen','The pump exchanges intracellular hydrogen for luminal potassium.'],['Selective blockade of H2 receptors without affecting the pump','That describes another upstream drug class.'],['Neutralization of acid already present by a simple base','This describes an antacid rather than pump inactivation.'],['Direct eradication of every gastric bacterium','Acid suppression is not itself universal antibacterial eradication.']], 'Proton pump inhibitors inhibit the parietal-cell H/K ATPase, a final common pathway of acid secretion stimulated by several upstream signals. Their action differs from H2 receptor blockade and luminal acid neutralization. Clinical duration can exceed the plasma half-life because new functional pumps must replace inhibited ones.','Identify the final secretory pump targeted by proton pump inhibitors.',pharm),
q(792,P,'H2 receptor antagonism','application','Separate receptor-level reduction of a secretory stimulus from direct acid neutralization.','A gastric acid-suppressing drug competitively blocks histamine H2 receptors on parietal cells. Which intracellular stimulus for secretion is principally reduced?',[
['Histamine-driven cyclic AMP signaling','H2 receptor signaling normally promotes the parietal-cell acid secretory response.'],['Bacterial peptidoglycan synthesis','This is unrelated to parietal-cell histamine signaling.'],['Direct binding of acid molecules in the lumen','Receptor antagonism differs from chemical neutralization by antacids.'],['All gastrin synthesis through irreversible gene deletion','Competitive receptor blockade does not delete the gastrin gene.']], 'Parietal-cell H2 receptors respond to histamine through signaling that increases cAMP and supports acid secretion. H2 antagonists reduce that stimulus without directly neutralizing existing luminal acid. Other secretory signals and drug-specific properties influence the clinical effect, so receptor selectivity does not imply complete shutdown of every gastric function.','Explain receptor-level acid suppression through H2 signaling blockade.',pharm),
q(793,P,'Osmotic laxative action','application','Identify luminal water retention rather than a systemic endocrine mechanism.','A poorly absorbed solute remains in the intestinal lumen and softens stool by retaining water. Which mechanism best explains its laxative effect?',[
['An increased luminal osmotic load','Water is retained in the bowel with the poorly absorbed substance.'],['Complete inhibition of renal water excretion','The principal site described is intestinal rather than renal.'],['Permanent paralysis of every colonic smooth muscle cell','Water retention does not require complete paralysis.'],['Direct replacement of all intestinal neurons','An osmotic agent does not act through neuronal replacement.']], 'Poorly absorbed osmotic substances retain water within the intestinal lumen, increasing stool water content. Their effect depends on dose, absorption, and the patient fluid and electrolyte state. This differs from stimulant laxatives that act more directly on intestinal motility or secretion, and it does not justify assuming every laxative has the same mechanism.','Explain luminal water retention by an osmotic laxative.',pharm),
q(794,P,'SGLT2 inhibition','integration','Trace reduced proximal glucose reclamation to a filtered-substrate-dependent urinary effect.','A drug inhibits sodium-glucose cotransporter 2 in the proximal tubule. Which immediate renal effect most directly follows when filtered glucose is available?',[
['Increased urinary glucose excretion','Blocking proximal reclamation leaves more filtered glucose in tubular fluid.'],['Complete blockade of glucose filtration','Glucose filtration occurs at the glomerulus, upstream of the transporter.'],['Direct stimulation of pancreatic insulin granule release','This is not the renal transporter mechanism.'],['Increased proximal glucose reabsorption','That is opposite to the effect of transporter inhibition.']], 'SGLT2 inhibition reduces proximal tubular glucose reabsorption and promotes glucosuria, with associated osmotic and sodium-handling effects. The action is distinct from an insulin secretagogue and depends partly on filtered substrate and kidney function. This mechanistic description does not cover every clinical benefit or risk of the drug class.','Identify glucosuria from pharmacologic inhibition of proximal SGLT2.',pharm),
q(795,P,'DPP-4 inhibition','integration','Relate reduced hormone breakdown to glucose-dependent rather than unrestricted insulin secretion.','A diabetes drug inhibits the enzyme that rapidly degrades incretin hormones. Which response best describes its intended physiologic effect?',[
['Prolonged incretin action supporting glucose-dependent insulin secretion','DPP-4 inhibition increases availability of endogenous incretin signaling.'],['Direct irreversible closure of beta-cell potassium channels','That is a secretagogue mechanism different from incretin preservation.'],['Complete elimination of hepatic insulin clearance','The drug does not work by abolishing all insulin degradation.'],['Inhibition of every intestinal carbohydrate enzyme','That describes a different absorption-directed mechanism.']], 'DPP-4 inhibitors prolong endogenous incretin activity, supporting insulin secretion and glucagon regulation in a glucose-dependent manner. This differs from forcing secretion through beta-cell potassium-channel closure. Glucose dependence lowers intrinsic hypoglycemia tendency, but combination drugs and patient factors can still create risk; it is not a guarantee that hypoglycemia never occurs.','Explain DPP-4 inhibition as preservation of endogenous incretin action.',pharm),
q(796,P,'Alpha-glucosidase inhibition','integration','Locate slowed carbohydrate digestion before absorption rather than renal glucose loss.','A diabetes medication delays brush-border breakdown of complex carbohydrates. Post-meal glucose rises are reduced, and gas production increases. Which site of action best explains both effects?',[
['Intestinal alpha-glucosidase inhibition','Less rapid monosaccharide generation slows absorption and leaves carbohydrate for fermentation.'],['Renal SGLT2 inhibition','This causes urinary glucose loss rather than delayed intestinal digestion.'],['Pancreatic beta-cell potassium-channel closure','That increases insulin secretion rather than directly delaying carbohydrate breakdown.'],['Hepatic HMG-CoA reductase inhibition','This is a cholesterol-synthesis target, not the described digestive mechanism.']], 'Alpha-glucosidase inhibitors slow intestinal conversion of dietary carbohydrates to absorbable monosaccharides, blunting postprandial glucose entry. Unabsorbed carbohydrate reaching the colon can be fermented, causing gas and other gastrointestinal effects. The mechanism differs from both renal glucosuria and direct insulin secretion.','Connect delayed carbohydrate digestion to postprandial glucose control and fermentation.',pharm),
q(797,P,'Microtubule-targeting gout therapy','integration','Connect altered cytoskeletal function to neutrophil inflammatory activity.','A drug used for selected gout flares binds tubulin and interferes with microtubule assembly. Which cellular effect most directly contributes to reduced crystal-induced inflammation?',[
['Impaired neutrophil trafficking and inflammatory functions','Microtubules support cellular transport and movement involved in the inflammatory response.'],['Immediate dissolution of all deposited urate crystals','The drug suppresses inflammation rather than directly removing the entire crystal burden.'],['Increased renal urate secretion as its primary mechanism','That is not the tubulin-binding anti-inflammatory action.'],['Inhibition of urate production by xanthine oxidase','This describes allopurinol-related urate lowering, not tubulin binding.']], 'Colchicine binds tubulin and alters microtubule-dependent cellular functions, reducing neutrophil participation in crystal inflammation. It does not rapidly eliminate urate stores and should be distinguished from long-term urate-lowering pathways. Its narrow safety considerations and interactions require drug-specific dosing and monitoring rather than an assumption that anti-inflammatory means harmless.','Distinguish colchicine microtubule effects from urate-lowering mechanisms.',pharm),
q(798,P,'Mineralocorticoid receptor blockade','integration','Predict potassium retention by blocking a distal sodium-retaining hormone signal.','A patient begins spironolactone. Which renal electrolyte effect is most consistent with antagonism of the mineralocorticoid receptor in distal nephron cells?',[
['Reduced potassium secretion with hyperkalemia risk','Blocking aldosterone-dependent sodium transport reduces the drive for distal potassium loss.'],['Obligate increased potassium excretion in every patient','This is opposite to the characteristic potassium-sparing tendency.'],['Direct blockade of NKCC2 as its primary action','That is the loop-diuretic transporter target.'],['Complete elimination of all glomerular filtration','Mineralocorticoid receptor blockade is not synonymous with stopping filtration.']], 'Spironolactone opposes aldosterone signaling, reducing distal sodium retention and potassium secretion. This creates potassium-sparing effects and a hyperkalemia risk, particularly with impaired kidney function or interacting drugs. The mechanism differs from loops and thiazides, whose increased distal sodium delivery can promote potassium loss.','Predict potassium retention from mineralocorticoid receptor antagonism.',pharm),
q(799,P,'Carbonic anhydrase inhibition','integration','Link proximal bicarbonate reclamation failure to urinary and systemic acid-base effects.','A drug inhibits carbonic anhydrase in proximal tubular cells. Which paired effect is most consistent with reduced bicarbonate reclamation?',[
['Bicarbonaturia with a tendency toward metabolic acidosis','Loss of filtered bicarbonate reduces systemic alkali stores.'],['Complete bicarbonate retention with obligatory metabolic alkalosis','This reverses the expected effect of impaired reclamation.'],['Selective blockade of the collecting-duct ADH receptor','That is a water-permeability pathway rather than carbonic anhydrase inhibition.'],['Direct enhancement of gastric acid neutralization without renal action','The stem specifies a proximal renal enzyme target.']], 'Carbonic anhydrase facilitates processes needed for proximal bicarbonate reabsorption. Inhibition promotes urinary bicarbonate loss and can cause metabolic acidosis as systemic bicarbonate falls. The bicarbonaturic effect changes as the filtered bicarbonate load declines, so the response is not indefinitely constant at the initial level.','Explain bicarbonaturia and acidosis after proximal carbonic anhydrase inhibition.',pharm),
q(800,P,'Direct oral factor Xa inhibition','integration','Identify a coagulation target that does not require antithrombin or vitamin K antagonism.','A patient receives a direct oral factor Xa inhibitor. Which mechanism most directly distinguishes the drug from unfractionated heparin and warfarin?',[
['Direct inhibition of factor Xa activity','The drug targets Xa without relying on antithrombin potentiation or vitamin K recycling inhibition.'],['Acceleration of antithrombin-mediated inhibition as its required mechanism','This describes heparin-related action rather than a direct Xa inhibitor.'],['Inhibition of vitamin K epoxide reductase','This is the warfarin mechanism rather than direct Xa target inhibition.'],['Irreversible platelet P2Y12 blockade','That is an antiplatelet rather than the specified factor Xa action.']], 'Direct factor Xa inhibitors suppress a key coagulation step through direct target binding. They differ from heparin, which acts through antithrombin, and warfarin, which reduces vitamin K-dependent protein activation. These distinctions affect monitoring, interactions, and reversal planning, so anticoagulants should not be treated as interchangeable solely because they prevent thrombosis.','Distinguish direct factor Xa inhibition from indirect anticoagulant mechanisms.',pharm),
];

